      { q: { id: "Menurut 'Ikrimah dari Ibnu 'Abbas, apa yang pertama kali dinasakh dalam Al-Qur'an?", ar: "أول ما نُسخ من القرآن عند عكرمة عن ابن عباس…" }, o: [{ id: "Hukum khamr", ar: "الخمر" }, { id: "Urusan kiblat", ar: "شأن القبلة" }, { id: "Puasa 'Asyura", ar: "عاشوراء" }, { id: "Qishash", ar: "القصاص" }], j: 1, b: { id: "Dari 2:115 ke perintah menghadap Masjidil Haram (2:150).", ar: "شأن القبلة." } }
